+      font-size: 1.05rem;
+    }
+
+    .faq-list {
+      display: grid;
+      gap: 1rem;
+    }
+
+    .example {
+      border: 1px solid var(--color-border);
+      border-radius: 1.25rem;
+      background: linear-gradient(180deg, var(--color-surface-2) 0%, #121a31 100%);
+      overflow: clip;
+    }
+
+    .example h2 {
+      margin: 0;
+      font-size: 1.05rem;
+    }
+
+    .example button {
+      appearance: none;
+      width: 100%;
+      border: 0;
+      margin: 0;
+      padding: 1.1rem 1.25rem;
+      background: transparent;
