+      text-align: left;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 1rem;
+      cursor: pointer;
+    }
+
+    .example button:hover {
+      background: #1b2850;
+    }
+
+    .example button:focus-visible {
+      outline: 3px solid var(--color-focus);
+      outline-offset: -3px;
+    }
+
+    .example button::after {
+      content: "+";
+      display: grid;
+      place-items: center;
+      width: 2rem;
+      height: 2rem;
+      flex: none;
+      border-radius: 999px;
