+
+      .example button,
+      .details {
+        padding-left: 1.5rem;
+        padding-right: 1.5rem;
+      }
+
+      .details {
+        padding-bottom: 1.35rem;
+      }
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      html {
+        scroll-behavior: auto;
+      }
+
+      *,
+      *::before,
+      *::after {
+        transition-duration: 0.01ms !important;
+        animation-duration: 0.01ms !important;
+        animation-iteration-count: 1 !important;
+      }
+    }
+
+    @media (forced-colors: active) {
+      :root {
+        --color-bg: Canvas;
+        --color-surface: Canvas;
+        --color-surface-2: Canvas;
+        --color-text: CanvasText;
+        --color-muted-text: CanvasText;
+        --color-border: ButtonBorder;
+        --color-accent: LinkText;
+        --color-accent-strong: LinkText;
+        --color-focus: Highlight;
+      }
+
+      body {
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      .hero,
+      .example {
+        background: Canvas;
+      }
+
+      .example button:hover,
+      .example button[aria-expanded="true"]::after {
+        background: ButtonFace;
+      }
+
+      .example button::after {
+        border-color: ButtonBorder;
+        color: ButtonText;
+      }
+
+      .skip-link {
+        background: Highlight;
+        color: HighlightText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main">Skip to main content</a>
+
+  <main id="main" tabindex="-1">
+    <section class="hero" aria-labelledby="page-title">
+      <h1 id="page-title">Cat FAQ</h1>
+      <p class="intro">A few quick answers about cats, their habits, and what makes them so fascinating.</p>
+    </section>
+
+    <section class="faq-list" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <h2>
+          <button type="button" aria-expanded="false" aria-controls="cat-faq-1">
+            Why do cats purr?
+          </button>
+        </h2>
+        <div class="details" id="cat-faq-1">
+          <p>Cats purr when they are relaxed, but they may also purr when they are nervous, in pain, or trying to comfort themselves. It is one of their many ways of communicating.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <h2>
+          <button type="button" aria-expanded="false" aria-controls="cat-faq-2">
+            Do cats need daily play?
+          </button>
+        </h2>
+        <div class="details" id="cat-faq-2">
+          <p>Yes. Short, consistent play sessions help cats stay fit, reduce boredom, and satisfy their hunting instincts. Wand toys and puzzle feeders are especially useful.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <h2>
+          <button type="button" aria-expanded="false" aria-controls="cat-faq-3">
+            Why do cats stare at people?
+          </button>
+        </h2>
+        <div class="details" id="cat-faq-3">
+          <p>Sometimes they are curious, sometimes they are asking for food, and sometimes they are simply observing. A slow blink from a cat is often a friendly sign.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <h2>
+          <button type="button" aria-expanded="false" aria-controls="cat-faq-4">
+            Are cats really independent?
+          </button>
+        </h2>
+        <div class="details" id="cat-faq-4">
+          <p>Cats often seem independent, but they still rely on people for care, enrichment, and routine. Many cats form strong bonds and seek attention on their own terms.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <h2>
+          <button type="button" aria-expanded="false" aria-controls="cat-faq-5">
+            Why do cats knead blankets?
+          </button>
+        </h2>
+        <div class="details" id="cat-faq-5">
+          <p>Kneading is a soothing behavior that begins in kittenhood. Adult cats often knead when they feel safe, content, or ready to settle down.</p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll('.example').forEach((item) => {
+      const button = item.querySelector('button[aria-expanded]');
+      const panel = item.querySelector('.details');
+
+      if (!button || !panel) {
+        return;
+      }
+
+      button.setAttribute('aria-expanded', 'false');
+      panel.hidden = true;
+
+      const setOpen = (open) => {
+        button.setAttribute('aria-expanded', String(open));
+        panel.hidden = !open;
+      };
+
+      button.addEventListener('click', () => {
+        setOpen(button.getAttribute('aria-expanded') !== 'true');
+      });
+
+      button.addEventListener('keydown', (event) => {
+        if (event.key === 'Escape' && button.getAttribute('aria-expanded') === 'true') {
+          setOpen(false);
+          button.focus();
+        }
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
